(() => {
  const clean = (s) => (s || '').replace(/\u00a0/g, ' ').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2; };
  const dp = [...document.querySelectorAll('div')].filter((e) => /datepicker|date-panel|picker/i.test((e.className || '').toString()) && vis(e) && clean(e.innerText).length > 3);
  return dp.map((e) => ({cls: (e.className || '').toString().slice(0, 60), text: clean(e.innerText).slice(0, 260),
    cells: [...e.querySelectorAll('*')].filter((x) => vis(x) && x.children.length === 0 && clean(x.innerText).length > 0 && clean(x.innerText).length < 8)
      .map((x) => x.tagName + '.' + (x.className || '').toString().slice(0, 30) + ':' + clean(x.innerText)).slice(0, 45)})).slice(0, 4)
})()
